/** Torche.icon(nom, {className, size, label}) → <svg>. Glyphes (24 px) ou emblèmes (game-icons, 512 px). */
T.icon = function (name, opt) {
  opt = opt || {};
  var body = G[name], vb = 24, emb = false;
  if (!body && EMB[name]) { body = EMB[name]; vb = 512; emb = true; }
  if (!body) return '';
  var style = opt.size ? ' style="width:' + opt.size + 'px;height:' + opt.size + 'px"' : '';
  var a11y = opt.label ? ' role="img" aria-label="' + esc(opt.label) + '"' : ' aria-hidden="true"';
  return '<svg class="' + cx('t-ico', emb && 't-ico--emb', opt.className) + '" viewBox="0 0 ' + vb + ' ' + vb + '" fill="currentColor"' + style + a11y + ' focusable="false">' + body + '</svg>';
};
T.icon.glyphs = Object.keys(G);
T.icon.emblems = Object.keys(EMB);

/* Petit balisage dans les textes de cartes : {hp} {torch} {hit} {or} {sigma} → glyphes. */
function rich(text) {
  return esc(text).replace(/(\d+\s?)?\{(hp|torch|hit|or|sigma)\}([.,;:!?)]*)/g, function (_, num, k, punct) {
    var map = { hp: ['heart', 'dégâts', 't-ink-hp'], torch: ['flame', 'torche', 't-ink-torch'], hit: ['swords', 'coups', 't-ink-hit'], or: ['star', 'Or', 't-ink-gold'], sigma: ['sigma', 'total', ''] }[k];
    return '<span class="t-nowrap">' + (num ? num.trim() + '\u00a0' : '') + T.icon(map[0], { className: 't-ico--inline ' + map[2], label: map[1] }) + (punct || '') + '</span>';
  });
}
T.util.rich = rich;

