  plus: 420, flip: 480, transmute: 520, aegis: 800, prayer: 1000, shortcut: 700, curse: 520,
  gauge: 260, seal: 360, ready: 320, hit: 420, down: 640, revive: 1000, bossHit: 900, frost: 1000,
  summon: 560, fury: 1200, round: 1400, shatter: 900, flameOut: 520, doors: 1300, fan: 520, give: 560,
  xp: 640, level: 1400, floor: 2200, ending: 1600
