    crack.style.width = b.w + 'px'; crack.style.height = b.h + 'px'; crack.style.transform = 'translate(' + b.x + 'px,' + b.y + 'px)';
    tl.add(crack, [{ opacity: 0 }, { opacity: 1, offset: .5 }, { opacity: 0 }], { duration: 300, easing: 'linear' });
    burst(tl, lay, b.x + b.w * .52, b.y + b.h * .44, 't-flash--gold', 120, 420, 220);
